/*
D = B + f(A) 
        B = A+C 
        f(x) = x  where x ∈ ℝ 
        where 
        A ∈ ℝ
        C ∈ ℝ
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT D;
    DT B;

    template<typename REAL>
    REAL f(
        const REAL & x)
    {
        return x;    
    }
    heartlib(
        const double & A,
        const double & C)
    {

        // B = A+C
        B = A + C;
        // D = B + f(A)
        D = B + f(A);
    }
};

