outputs.matlab:
function output = heartlib(A, C)
% output = heartlib(A, C)
%
%    D = B + f(A) 
%            B = A+C 
%            f(x) = x  where x ∈ ℝ 
%            where 
%            A ∈ ℝ
%            C ∈ ℝ
    assert(numel(A) == 1);
    assert(numel(C) == 1);

    % B = A+C

    B = A + C;
    % D = B + f(A)

    D = B + f(A);
    function [ret] = f(x)
        assert(numel(x) == 1);

        ret = x;
    end

    output.D = D;
    output.B = B;
    output.f = @f;
end

